import fs from 'node:fs';import {chromium} from 'playwright';import {PNG} from 'pngjs';import crypto from 'node:crypto';
const cases=[[9,.8],[77,.8],[9,.2],[127,.8]].map(([source,alpha])=>({source,alpha,background:[15,31,63]}));
function predictions(c){const a=Math.round(c.alpha*255);return {straightRound:c.background.map(v=>Math.round(c.source*c.alpha+v*(1-c.alpha))),premulRounded255Then256:c.background.map(v=>Math.round(c.source*a/255)+Math.floor(v*(256-a)/256)),scaled256Both:c.background.map(v=>Math.floor(c.source*(a+1)/256)+Math.floor(v*(256-a)/256))};}
for(const c of cases)c.predictions=predictions(c);
const protocol={status:'Predictions saved before independent holdout rendering; original window already observed',cases,scope:'Independent scalar source images/CSS controls only. No product code/CSS/image measurements used to generate predictions.'};const protocolBytes=Buffer.from(JSON.stringify(protocol,null,2));fs.writeFileSync('.cache/file-transmission-browser-01/ALPHA-HOLDOUT-PREDICTIONS.json',protocolBytes);
const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:800,height:600},deviceScaleFactor:1});const rows=[];
for(const c of cases)for(const kind of ['opaque-png-opacity','solid-opacity','solid-rgba','alpha-png']){const p=new PNG({width:2,height:2});for(let i=0;i<p.data.length;i+=4)p.data.set([c.source,c.source,c.source,kind==='alpha-png'?Math.round(c.alpha*255):255],i);rows.push({...c,kind,src:'data:image/png;base64,'+PNG.sync.write(p).toString('base64')});}
await page.setContent('<style>body{margin:0}#grid{display:grid;grid-template-columns:repeat(4,32px)}.cell{position:relative;width:32px;height:32px}.source{position:absolute;inset:0;width:32px;height:32px}</style><div id="grid">'+rows.map(c=>'<div class="cell" style="background:rgb('+c.background.join(',')+')">'+(c.kind.includes('png')?'<img class="source" src="'+c.src+'" style="opacity:'+(c.kind==='alpha-png'?1:c.alpha)+'">':'<div class="source" style="background:'+(c.kind==='solid-rgba'?'rgba('+c.source+','+c.source+','+c.source+','+c.alpha+')':'rgb('+c.source+','+c.source+','+c.source+');opacity:'+c.alpha)+'"></div>')+'</div>').join('')+'</div>');await page.evaluate(()=>Promise.all([...document.images].map(x=>x.decode())));const bytes=await page.screenshot(),p=PNG.sync.read(bytes);
for(let i=0;i<rows.length;i++){const c=rows[i],at=((Math.floor(i/4)*32+16)*p.width+(i%4)*32+16)*4;c.actualRGB=Array.from(p.data.subarray(at,at+3));delete c.src;}
const cdp=await page.context().newCDPSession(page);const result={protocolSHA256:crypto.createHash('sha256').update(protocolBytes).digest('hex'),browser:await cdp.send('Browser.getVersion'),rows};fs.writeFileSync('.cache/file-transmission-browser-01/ALPHA-HOLDOUT.json',JSON.stringify(result,null,2));fs.writeFileSync('.cache/file-transmission-browser-01/ALPHA-HOLDOUT.png',bytes);console.log(JSON.stringify(rows.filter(x=>x.kind==='opaque-png-opacity')));}finally{await browser.close();}
